      "verification": {
        "what": "backfilled feature counts",
        "how": "compare counts in feature store and data warehouse",
        "expected": "counts match"
      },
      "rollback": {
        "trigger": "backfill fails",
        "action": "restore previous state",
        "safety_guard": "check data integrity",
        "restores_state": "previous_feature_state",
        "restoration_evidence": "data integrity verified"
      }
    },
    {
      "id": "deploy_feast_online_serving",
      "description": "Deploy Feast for online serving",
      "action": "deploy",
